// Ambil item dari RSS Google News, saring yang masih segar dan relevan.
// Google News tidak punya API resmi; RSS ini yang dipakai, dan terbukti hidup.
const cfg = $('CONFIG').first().json;
const masukan = $input.first().json;
const xml = masukan.data || masukan.body || '';
const batasJam = Number(cfg.maks_umur_jam || 24);
const maksItem = Number(cfg.maks_item || 1);
const kataKunci = String(cfg.kata_kunci || '')
  .split(',')
  .map((s) => s.trim().toLowerCase())
  .filter(Boolean);

function ambil(teks, tag) {
  const pola = new RegExp('<' + tag + '>([\\s\\S]*?)<\\/' + tag + '>');
  const m = teks.match(pola);
  return m ? m[1].replace(/<!\[CDATA\[|\]\]>/g, '').trim() : '';
}

const blok = String(xml).split('<item>').slice(1);
const sekarang = Date.now();
const hasil = [];

for (const b of blok) {
  const judul = ambil(b, 'title');
  const tautan = ambil(b, 'link');
  const tanggal = ambil(b, 'pubDate');
  const sumber = ambil(b, 'source');
  if (!judul || !tautan) continue;

  const waktu = Date.parse(tanggal);
  if (Number.isNaN(waktu)) continue;

  const umurJam = (sekarang - waktu) / 3600000;
  if (umurJam > batasJam) continue; // berita lama langsung dibuang

  const teksCari = (judul + ' ' + sumber).toLowerCase();
  const cocok = kataKunci.filter((k) => teksCari.includes(k));
  if (kataKunci.length && cocok.length === 0) continue;

  // Sidik = judul + waktu terbit. URL Google News berubah-ubah, judul tidak.
  const sidik =
    judul.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 70) +
    '-' +
    waktu;

  hasil.push({
    judul,
    tautan,
    sumber,
    terbit: new Date(waktu).toISOString(),
    umur_jam: Math.round(umurJam * 10) / 10,
    kata_kunci: cocok.join(', '),
    sidik,
  });
}

hasil.sort((a, b) => a.umur_jam - b.umur_jam); // paling baru lebih dulu
return hasil.slice(0, maksItem).map((x) => ({ json: x }));

// Buang kandidat yang sidiknya sudah ada di tab `seen`.
// Input node ini adalah isi tab `seen`; kandidat diambil dari node Parse feed.
const kandidat = $('Parse feed').all().map((i) => i.json);
const sudah = new Set(
  $input
    .all()
    .map((i) => String(i.json.sidik || i.json.Sidik || '').trim())
    .filter(Boolean)
);
return kandidat.filter((k) => !sudah.has(k.sidik)).map((k) => ({ json: k }));

// Ubah balasan model menjadi tiga bagian. Kalau model mengembalikan teks
// berbungkus ```json, bungkus itu dibuang dulu - ini penyebab gagal paling umum.
const cfg = $('CONFIG').first().json;
const asal = $('Parse feed').first().json;
const balasan = $input.first().json;

const isi =
  balasan.choices &&
  balasan.choices[0] &&
  balasan.choices[0].message &&
  balasan.choices[0].message.content
    ? balasan.choices[0].message.content
    : '';

const bersih = String(isi)
  .replace(/^\s*```(?:json)?/i, '')
  .replace(/```\s*$/, '')
  .trim();

let bagian;
try {
  bagian = JSON.parse(bersih);
} catch (e) {
  // Kalau model tidak menurut format, jangan buang beritanya: simpan mentah.
  bagian = { pemicu: bersih, sudut: '', ajakan: '' };
}

return [
  {
    json: {
      judul: asal.judul,
      sumber: asal.sumber,
      tautan: asal.tautan,
      terbit: asal.terbit,
      pemicu: bagian.pemicu || '',
      sudut: bagian.sudut || '',
      ajakan: bagian.ajakan || '',
      dibuat: new Date().toISOString(),
      sidik: asal.sidik,
    },
  },
];
